#!/bin/sh
#
# Post-install script of the app's .deb and .rpm (generated by grafida/shell-packager).
#
# Refreshes the desktop and icon caches, and removes the system-wide desktop entry and hicolor
# icons of an earlier build of this app under another id (linux.replaces), but only when that
# entry starts a program called NAME. It never touches anything under a user's home directory:
# a per-user entry left by the tarball's install.sh is the user's to remove (./install.sh
# --uninstall), and the user's data is never ours to delete.

set -e

NAME=@NAME@
REPLACES=@REPLACES@
APPS_DIR=/usr/share/applications
ICONS_DIR=/usr/share/icons/hicolor

exec_program() {
    sed -n '/^\[Desktop Entry\]/,/^\[/ s/^Exec=//p' "$1" | head -n 1 \
        | sed -e 's/[[:space:]]*%[a-zA-Z]//g' -e 's/[[:space:]]*$//' -e 's/^"\(.*\)"$/\1/'
}

for old in $REPLACES; do
    entry=$APPS_DIR/$old.desktop
    [ -f "$entry" ] || continue
    program=$(exec_program "$entry")
    case $program in
        "$NAME" | */"$NAME") ;;
        *) continue ;;
    esac
    rm -f "$entry"
    for icon in "$ICONS_DIR"/*/apps/"$old".png "$ICONS_DIR"/*/apps/"$old".svg; do
        if [ -e "$icon" ]; then rm -f "$icon"; fi
    done
done

if command -v update-desktop-database >/dev/null 2>&1; then update-desktop-database -q "$APPS_DIR" || true; fi
if command -v gtk-update-icon-cache >/dev/null 2>&1 && [ -d "$ICONS_DIR" ]; then gtk-update-icon-cache -q -f -t "$ICONS_DIR" || true; fi

exit 0
